import sympy

x = sympy.Symbol('x')

CONDITION_LABELS = [
    "H_1: p is an odd prime number",
    "H_2: I is the ideal generated by x^2 + 1",
    "not_Q: The factor ring F_p(x) mod I is a field iff p = 3 mod 4 is false"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    try:
        if isinstance(witness, (tuple, list)):
            p = witness[0]
        else:
            p = witness
            
        if not isinstance(p, (int, sympy.Integer)):
            h1 = False
        else:
            p_int = int(p)
            h1 = sympy.isprime(abs(p_int)) and (p_int % 2 != 0)
    except Exception:
        h1 = False

    try:
        if isinstance(witness, (tuple, list)) and len(witness) >= 2:
            I_val = witness[1]
            if str(I_val) == "x**2 + 1" or I_val == x**2 + 1:
                h2 = True
            else:
                h2 = False
        else:
            h2 = True
    except Exception:
        h2 = False

    try:
        if isinstance(witness, (tuple, list)):
            p = witness[0]
        else:
            p = witness
            
        p_int = int(p)
        
        # F_p[x]/I is a field if and only if x^2 + 1 is irreducible over F_{|p|}
        # For odd primes, this is true if and only if |p| = 3 mod 4
        is_field = (abs(p_int) % 4 == 3)
        
        # The conclusion states: F_p[x]/I is a field iff p = 3 mod 4
        conclusion = (is_field == (p_int % 4 == 3))
        
        # We want the negation of the conclusion
        neg_q = not conclusion
    except Exception:
        neg_q = False

    return [bool(h1), bool(h2), bool(neg_q)]